export function captionValue(captionKey, language = "ka", values = {}) {
  const text = captionValues[captionKey]?.[language] ?? captionValues[captionKey]?.ka ?? captionKey;
  return text.replace(/\{(\w+)\}/g, (match, name) => String(values[name] ?? match));
}

// Materialize a caption-key tree for existing invitation layouts.
export function resolveCaptionKeys(captionKeys, language) {
  if (typeof captionKeys === "number") return captionKeys;
  if (typeof captionKeys === "string") return captionValue(captionKeys, language);
  if (Array.isArray(captionKeys)) return captionKeys.map(key => resolveCaptionKeys(key, language));
  return Object.fromEntries(Object.entries(captionKeys).map(([name, key]) => [name, resolveCaptionKeys(key, language)]));
}

export function createCaptionCopy(captionKeys) {
  return { en: resolveCaptionKeys(captionKeys, "en"), ka: resolveCaptionKeys(captionKeys, "ka") };
}
